(() => {
  const out = [];
  document.querySelectorAll('.select-label, .select-milestone, .select-assignees').forEach(el => {
    out.push({cls: el.className, html: el.outerHTML.slice(0, 600)});
  });
  return out;
})()

(() => {
  const el = document.querySelector('#issue-labels');
  const menu = document.querySelector('.ui.dropdown .menu, .menu');
  return { found: !!el, sidebar: (document.querySelector('.issue-sidebar')||{}).outerHTML ? 'yes':'no' };
})()

(() => {
  const sels = Array.from(document.querySelectorAll('[class*="label"], [class*="assignee"], [class*="milestone"]')).slice(0,40).map(e => e.tagName + '.' + e.className);
  return sels;
})()

(() => {
  const els = Array.from(document.querySelectorAll('*')).filter(e => e.children.length===0 && e.textContent.trim()==='No labels');
  if (!els.length) return 'not found';
  let n = els[0];
  for (let i=0;i<5 && n.parentElement;i++) n = n.parentElement;
  return n.outerHTML.slice(0, 4000);
})()

(() => {
  const el = Array.from(document.querySelectorAll('*')).filter(e => e.children.length===0 && e.textContent.trim()==='No labels')[0];
  let n = el;
  while (n.parentElement && n.textContent.length < 3500) n = n.parentElement;
  return n.outerHTML.slice(0, 3500);
})()

(() => {
  const main = document.querySelector('.issue-content');
  const kids = Array.from(main.children).map(k => k.tagName+'.'+k.className);
  const right = main.querySelector('.issue-content-right');
  return {kids, rightHtml: right ? right.outerHTML.slice(0,3000) : 'none'};
})()

(() => {
  const right = document.querySelector('.issue-content-right');
  const html = right.outerHTML;
  const i = html.indexOf('select-label');
  return { idx: i, snippet: i>=0 ? html.slice(i-300, i+2500) : html.slice(3000, 7000) };
})()
